/**
 * Writes THIRD_PARTY_LICENSES.md (PLAN §5, §11): every production npm package (from pnpm's own license
 * data), the bundled models and WASM (models/checksums.json), the container images the deploy stack
 * pins, and the test data. Run: pnpm licenses:third-party. Do not edit the output by hand.
 */
import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

interface PnpmLicenseEntry {
  name: string;
  versions: string[];
  license: string;
  homepage?: string;
}

const root = join(fileURLToPath(new URL('.', import.meta.url)), '..');

export function npmTable(byLicense: Record<string, PnpmLicenseEntry[]>): string[] {
  const rows = Object.entries(byLicense)
    .flatMap(([license, pkgs]) => pkgs.map((p) => ({ name: p.name, versions: p.versions.join(', '), license })))
    .sort((a, b) => a.name.localeCompare(b.name));
  return ['| Package | Version | License |', '|---|---|---|', ...rows.map((r) => `| ${r.name} | ${r.versions} | ${r.license} |`)];
}

function main(): void {
  const byLicense = JSON.parse(execSync('pnpm licenses list --json --prod --recursive', { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 }) || '{}') as Record<string, PnpmLicenseEntry[]>;
  const models = (JSON.parse(readFileSync(join(root, 'models', 'checksums.json'), 'utf8')) as { files: { name: string; license: string; upstream?: string; source: string }[] }).files;
  const images = [...readFileSync(join(root, 'deploy', 'docker-compose.yml'), 'utf8').matchAll(/^\s*image:\s*(\S+)/gm)].map((m) => m[1] ?? '').filter((i) => !i.startsWith('survey-anything/'));
  const known: Record<string, string> = {
    'caddy': 'Apache-2.0 (TLS proxy; outside the media plane, PLAN C14)',
    'airensoft/ovenmediaengine': 'AGPL-3.0-only (media plane; source: https://github.com/OvenMediaLabs/OvenMediaEngine)',
    'axllent/mailpit': 'MIT (local test mail server)',
  };
  const out = [
    '# Third-party licenses',
    '',
    'Generated by `pnpm licenses:third-party` from pnpm\'s license data, `models/checksums.json` and `deploy/docker-compose.yml`. Survey Anything itself is AGPL-3.0-only (`LICENSE`).',
    '',
    '## Bundled in the extension: models and runtime files',
    '',
    '| File | License | Upstream |',
    '|---|---|---|',
    ...models.map((m) => `| ${m.name} | ${m.license} | ${(m.upstream ?? m.source).replace(/\|/g, '/')} |`),
    '',
    'The fire/smoke weights are a derivative of Megvii\'s YOLOX-tiny COCO weights (Apache-2.0), trained on the CC0 part of D-Fire (`models/fire-smoke/MODEL_CARD.md`).',
    '',
    '## Production npm packages (extension, backend, viewer)',
    '',
    ...npmTable(byLicense),
    '',
    '## Container images in the deploy stack (not redistributed by this repository)',
    '',
    '| Image | License |',
    '|---|---|',
    ...images.map((i) => `| \`${i}\` | ${Object.entries(known).find(([k]) => i.startsWith(k))?.[1] ?? 'see the image\'s source'} |`),
    '| `confirm-gate-mcp` 0.8.0 (built from `deploy/gate/Dockerfile`, PyPI) | MIT |',
    '',
    '## Test and demo data',
    '',
    '| Data | License |',
    '|---|---|',
    '| `bench/fixtures/dfire/*.jpg` (three D-Fire test images; also used by `demo/`) | CC0 1.0 (D-Fire, https://github.com/gaiasd/DFireDataset) |',
    '| `bench/fixtures/dog.jpg` | Apache-2.0 (from the YOLOX repository) |',
    '| Bench sets built by `bench/prepare_sets.py` (not in git) | CC0 1.0 (D-Fire, `PublicDataset*` images excluded) |',
    '',
  ];
  writeFileSync(join(root, 'THIRD_PARTY_LICENSES.md'), out.join('\n'));
  console.info(`wrote THIRD_PARTY_LICENSES.md (${Object.values(byLicense).flat().length} npm packages, ${models.length} bundled files, ${images.length} images)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
